//! The stage-4 real-machine binding gate (parity plan › stage 4, ADR 0104): bones-bind.moho
//! was generated by Moho Pro 14.4 (Lua: gen_bind.lua) — a bone rig ("BindRig", two bones,
//! the child at the parent's tip via the animated-parent channel) nested over gradients
//! canvas's Layer 1, all 34 mesh points classic-bound to the swing bone, whose angle keys
//! run 0 → π/2 → π linearly over frames 0/12/24. Moho's own FileRender frames (transparent,
//! document resolution) are the truth; this test renders the *imported* document through
//! the CPU oracle and compares content masks exactly like the stage-2 camera gate
//! (translation-aligned F1 on 4px cells).
//!
//! Negative control: the same document with every shape's bone binding stripped must NOT
//! match Moho's posed frames — the rotation is bone-borne, so an unbound render stays at
//! rest and the aligned overlap collapses. Without this, a gate that never moved could
//! pass on stroke baseline alone.

use anicraft_mohoproj_import::import_path;
use std::path::{Path, PathBuf};
use std::sync::Arc;

fn corpus() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("MAOHOU_FIXTURES") {
        let p = PathBuf::from(dir);
        if p.is_dir() {
            return Some(p);
        }
    }
    let beside = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../maop-corpus/maop");
    beside.is_dir().then_some(beside)
}

/// Downsampled boolean content mask (alpha > 24), cell = `step` px, any-content vote.
fn content_mask(px: &[u8], w: u32, h: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let gw = w / step;
    let gh = h / step;
    let mut m = vec![false; (gw * gh) as usize];
    for gy in 0..gh {
        for gx in 0..gw {
            let mut on = 0u32;
            for dy in 0..step {
                for dx in 0..step {
                    let a = px[(((gy * step + dy) * w + gx * step + dx) * 4 + 3) as usize];
                    if a > 24 {
                        on += 1;
                    }
                }
            }
            m[(gy * gw + gx) as usize] = on > 0;
        }
    }
    (gw, gh, m)
}

/// Best translation (within ±`range` cells) aligning `a` onto `b`, by F1 overlap.
fn best_shift(a: &[bool], b: &[bool], gw: u32, gh: u32, range: u32) -> (i64, i64, f64) {
    let (mut best_dx, mut best_dy) = (0i64, 0i64);
    let mut best_f1 = -1f64;
    let count = |dx: i64, dy: i64| -> f64 {
        let mut inter = 0u64;
        let mut na = 0u64;
        let mut nb = 0u64;
        for y in 0..gh as i64 {
            for x in 0..gw as i64 {
                let vb = b[(y as u32 * gw + x as u32) as usize];
                let ax = x - dx;
                let ay = y - dy;
                let va = ax >= 0 && ax < gw as i64 && ay >= 0 && ay < gh as i64 && a[(ay as u32 * gw + ax as u32) as usize];
                if va {
                    na += 1;
                }
                if vb {
                    nb += 1;
                }
                if va && vb {
                    inter += 1;
                }
            }
        }
        if na + nb == 0 {
            return 0.0;
        }
        2.0 * inter as f64 / (na + nb) as f64
    };
    for dy in -(range as i64)..=(range as i64) {
        for dx in -(range as i64)..=(range as i64) {
            let f1 = count(dx, dy);
            if f1 > best_f1 {
                best_f1 = f1;
                best_dx = dx;
                best_dy = dy;
            }
        }
    }
    (best_dx, best_dy, best_f1)
}

fn straight_rgba(ours: &anicraft_render::Pixmap) -> Vec<u8> {
    let mut rgba = Vec::with_capacity((ours.width * ours.height * 4) as usize);
    for p in &ours.data {
        let a = p[3];
        let un = |c: f32| if a > 0.0 { (c / a).clamp(0.0, 1.0) } else { 0.0 };
        rgba.extend_from_slice(&[(un(p[0]) * 255.0) as u8, (un(p[1]) * 255.0) as u8, (un(p[2]) * 255.0) as u8, (a * 255.0) as u8]);
    }
    rgba
}

/// The imported document rendered at `frame`, as a content mask plus raw F1 inputs.
fn render_mask(doc: &anicraft_doc::Document, frame: u32, step: u32) -> (u32, u32, Vec<bool>) {
    let (w, h) = (doc.stage.width, doc.stage.height);
    let dl = anicraft_doc::evaluate(doc, frame);
    let view = anicraft_render::View { transform: anicraft_geom::Affine::IDENTITY, width: w, height: h, background: None };
    let ours = anicraft_render::render(&dl, &view).unwrap().0;
    let rgba = straight_rgba(&ours);
    content_mask(&rgba, w, h, step)
}

#[test]
fn imported_binding_matches_moho_frames() {
    let Some(dir) = corpus() else {
        eprintln!("skipped: no maop-corpus beside the workspace");
        return;
    };
    let path = dir.join("bones-bind.moho");
    if !path.is_file() {
        eprintln!("skipped: no bones-bind.moho in the corpus");
        return;
    }
    let (doc, report) = import_path(&path).unwrap_or_else(|e| panic!("bones-bind.moho: {e}"));
    // The rig arrived whole: a bone layer with the two-bone hierarchy, the linear angle
    // keys, and the canvas's 34 points bound to the swing bone.
    let rig = doc.timeline(0).layers.iter().find(|l| l.kind == anicraft_doc::LayerKind::Bone).unwrap();
    let sk = rig.skeleton.as_ref().unwrap();
    assert_eq!(sk.bones.len(), 2);
    assert_eq!(sk.bones[0].name, "swing");
    assert_eq!(sk.bones[1].name, "sub");
    assert_eq!(sk.bones[1].parent, Some(anicraft_doc::BoneId(0)), "the child hangs off the swing bone");
    // The angle channel imports y-flipped: Moho CCW 0→π/2→π reads screen-clockwise.
    let angles: Vec<f32> = [0.0, 12.0, 24.0].iter().map(|f| sk.bones[0].angle.sample_or(*f, 0.0)).collect();
    assert!((angles[1] + std::f32::consts::FRAC_PI_2).abs() < 1e-3, "{angles:?}");
    assert!((angles[2] + std::f32::consts::PI).abs() < 1e-3, "{angles:?}");
    // Every shape on the canvas rides bone 0 (whole-shape classic binding).
    let art = doc.timeline(0).layers.iter().find(|l| l.name == "Layer 1").unwrap();
    let mut bound = 0usize;
    let mut unbound = 0usize;
    for k in &art.keyframes {
        for el in &k.elements {
            if let anicraft_doc::ElementKind::Shape(s) = &el.kind {
                if s.bind == vec![(anicraft_doc::BoneId(0), 1.0)] {
                    bound += 1;
                } else if s.bind.is_empty() {
                    unbound += 1;
                }
            }
        }
    }
    println!("bound shapes {bound}, unbound {unbound}");
    assert!(bound > 0, "no shape arrived bound to the swing bone");
    assert!(!report.skipped.contains_key("shapes bound to several bones"), "{:?}", report.skipped);
    assert!(!report.skipped.contains_key("points bound to bones"), "{:?}", report.skipped);

    let (w, h) = (doc.stage.width, doc.stage.height);
    let step = 4u32;
    for (name, frame) in [("f0", 0u32), ("f12", 12), ("f24", 24)] {
        let Ok(moho_png) = std::fs::read(dir.join(format!("inputs/bones-bind-{name}.png"))) else {
            eprintln!("skipped {name}: no Moho render");
            continue;
        };
        let moho = anicraft_doc::decode_png(&moho_png).unwrap();
        assert_eq!((moho.width, moho.height), (w, h), "FileRender uses the document resolution");
        let (gw, gh, m_mask) = content_mask(&moho.rgba, w, h, step);
        let (gw2, gh2, o_mask) = render_mask(&doc, frame, step);
        assert_eq!((gw, gh), (gw2, gh2));
        let (dx, dy, f1) = best_shift(&o_mask, &m_mask, gw, gh, 75);
        println!("bones-bind {name}: best shift ({dx}, {dy}) cells = ({}px, {}px), aligned F1 {f1:.3}", dx * step as i64, dy * step as i64);

        // The negative control, on the POSED frames only: strip the bindings — the
        // artwork stays at rest while Moho's render follows the bone. (At frame 0 the
        // rig is at rest, so bound and unbound legitimately agree — the identity skin.)
        if frame > 0 {
            let mut flat = doc.clone();
            for l in flat.timeline_mut(0).layers.iter_mut() {
                let l = Arc::make_mut(l);
                for k in &mut l.keyframes {
                    let k = Arc::make_mut(k);
                    for el in &mut k.elements {
                        let el = Arc::make_mut(el);
                        if let anicraft_doc::ElementKind::Shape(s) = &mut el.kind {
                            s.bind.clear();
                        }
                    }
                }
            }
            let (_, _, u_mask) = render_mask(&flat, frame, step);
            let (_, _, uf1) = best_shift(&u_mask, &m_mask, gw, gh, 75);
            println!("bones-bind {name}: UNBOUND control F1 {uf1:.3}");
            let why = format!("bones-bind {name}: bound F1 {f1:.3} must beat the unbound control {uf1:.3} — the deformation is not bone-borne");
            assert!(f1 > uf1 + 0.05, "{why}");
        }
        let why = format!("bones-bind {name}: aligned overlap F1 {f1:.3} — the imported binding does not reproduce Moho's frame");
        assert!(f1 > 0.18, "{why}");
        let why = format!("bones-bind {name}: best shift ({dx}, {dy}) cells — the rig posed the artwork to the wrong place");
        assert!(dx.abs() <= 20 && dy.abs() <= 20, "{why}");
    }
}
